import { migrateFile } from '../src/migrate.mjs';

const args = process.argv.slice(2);
if (args.length < 2 || args.length > 3) {
  console.error('Usage: node bin/migrate.mjs INPUT OUTPUT [REGION_OVERRIDE]');
  process.exitCode = 1;
